package dev.industrialtechnology.space;

import java.util.*;import net.minecraft.world.*;import net.minecraft.nbt.*;import net.minecraft.entity.player.*;import net.minecraft.entity.item.EntityItem;import net.minecraft.item.*;import net.minecraft.tileentity.TileEntity;import net.minecraft.util.*;
/** Small root index, not one tile entity or saved position for every building block. */
public final class FacilityIndex extends WorldSavedData {
    public static int budget=512;
    public static final class Entry {String id,owner;int dim,x,y,z,facing,cursor,limit;boolean cleanup;NBTTagCompound payload=new NBTTagCompound();
        int wx(int a,int c){return x+LaunchFacilityPlan.dx(a,c,facing);}int wz(int a,int c){return z+LaunchFacilityPlan.dz(a,c,facing);}
        boolean contains(int xx,int yy,int zz){int a=xx-x,c=zz-z;int localX=LaunchFacilityPlan.dx(a,c,facing==4?5:facing==5?4:facing),localZ=LaunchFacilityPlan.dz(a,c,facing==4?5:facing==5?4:facing);return localX>=LaunchFacilityPlan.MIN_X&&localX<=LaunchFacilityPlan.MAX_X&&localZ>=LaunchFacilityPlan.MIN_Z&&localZ<=LaunchFacilityPlan.MAX_Z&&yy>=y-1&&yy<=y+LaunchFacilityPlan.MAX_Y;}
    }
    public final Map<String,Entry> entries=new LinkedHashMap<String,Entry>();
    public FacilityIndex(){super("industrialtech_launch_facilities");}public FacilityIndex(String n){super(n);}
    public static FacilityIndex get(World w){World root=net.minecraftforge.common.DimensionManager.getWorld(0);if(root==null)root=w;FacilityIndex d=(FacilityIndex)root.mapStorage.loadData(FacilityIndex.class,"industrialtech_launch_facilities");if(d==null){d=new FacilityIndex();root.mapStorage.setData("industrialtech_launch_facilities",d);}return d;}
    public Entry reserve(TileLaunchFacility t){Entry old=entries.get(t.facilityId);if(old!=null)return old;if(entries.size()>=64)return null;Entry e=new Entry();e.id=t.facilityId;e.owner=t.owner;e.dim=t.getWorldObj().provider.dimensionId;e.x=t.xCoord;e.y=t.yCoord;e.z=t.zCoord;e.facing=BlockSpaceMachine.front(t.getBlockMetadata());
        for(Entry other:entries.values())if(other.dim==e.dim&&overlaps(e,other))return null;entries.put(e.id,e);markDirty();return e;
    }
    private static boolean overlaps(Entry a,Entry b){int aminx=Integer.MAX_VALUE,amaxx=Integer.MIN_VALUE,aminz=aminx,amaxz=amaxx,bminx=aminx,bmaxx=amaxx,bminz=aminx,bmaxz=amaxx;for(int x:new int[]{LaunchFacilityPlan.MIN_X,LaunchFacilityPlan.MAX_X})for(int z:new int[]{LaunchFacilityPlan.MIN_Z,LaunchFacilityPlan.MAX_Z}){aminx=Math.min(aminx,a.wx(x,z));amaxx=Math.max(amaxx,a.wx(x,z));aminz=Math.min(aminz,a.wz(x,z));amaxz=Math.max(amaxz,a.wz(x,z));bminx=Math.min(bminx,b.wx(x,z));bmaxx=Math.max(bmaxx,b.wx(x,z));bminz=Math.min(bminz,b.wz(x,z));bmaxz=Math.max(bmaxz,b.wz(x,z));}return aminx<=bmaxx&&amaxx>=bminx&&aminz<=bmaxz&&amaxz>=bminz&&a.y-1<=b.y+LaunchFacilityPlan.MAX_Y&&a.y+LaunchFacilityPlan.MAX_Y>=b.y-1;}
    private Entry find(World w,int x,int y,int z){for(Entry e:entries.values())if(e.dim==w.provider.dimensionId&&e.contains(x,y,z))return e;return null;}
    public static void open(World w,int x,int y,int z,EntityPlayer p){Entry e=get(w).find(w,x,y,z);if(e==null||e.cleanup||!e.owner.equals(p.getUniqueID().toString()))return;w.getChunkFromChunkCoords(e.x>>4,e.z>>4);TileEntity t=w.getTileEntity(e.x,e.y,e.z);if(t instanceof TileLaunchFacility)p.openGui(dev.industrialtechnology.core.IndustrialTechnology.instance,2,w,e.x,e.y,e.z);}
    public static void request(World w,int x,int y,int z,EntityPlayer p){Entry e=get(w).find(w,x,y,z);if(e==null){TileEntity t=w.getTileEntity(x,y,z);if(t instanceof TileLaunchFacility&&((TileLaunchFacility)t).authorized(p))((TileLaunchFacility)t).dismantle("Dismantling facility");return;}if(!e.owner.equals(p.getUniqueID().toString()))return;w.getChunkFromChunkCoords(e.x>>4,e.z>>4);TileEntity t=w.getTileEntity(e.x,e.y,e.z);if(t instanceof TileLaunchFacility)((TileLaunchFacility)t).dismantle("Dismantling facility");}
    public static void destroyed(World w,int x,int y,int z){Entry e=get(w).find(w,x,y,z);if(e==null||e.cleanup)return;w.getChunkFromChunkCoords(e.x>>4,e.z>>4);TileEntity t=w.getTileEntity(e.x,e.y,e.z);if(t instanceof TileLaunchFacility)((TileLaunchFacility)t).dismantle("Facility damaged; recovering kit");}
    public static void destroyRoot(TileLaunchFacility t){FacilityIndex d=get(t.getWorldObj());Entry e=d.entries.get(t.facilityId);if(e!=null&&!e.cleanup){e.cleanup=true;e.cursor=0;e.limit=t.phase==2?LaunchFacilityPlan.CELLS.size():t.phase==1?t.cursor:0;e.payload=t.controllerPayload();d.markDirty();}}
    public static void tick(World w){if(w.isRemote||w.playerEntities.isEmpty())return;FacilityIndex d=get(w);Iterator<Entry> it=d.entries.values().iterator();while(it.hasNext()){Entry e=it.next();if(e.dim!=w.provider.dimensionId||!e.cleanup)continue;int used=0;while(e.cursor<e.limit&&used++<256&&budget-->0){LaunchFacilityPlan.Cell c=LaunchFacilityPlan.CELLS.get(e.cursor);int x=e.wx(c.x,c.z),y=e.y+c.y,z=e.wz(c.x,c.z);w.getChunkFromChunkCoords(x>>4,z>>4);if(w.getBlock(x,y,z)==LaunchFacilityRegistry.part&&w.getBlockMetadata(x,y,z)==c.kind){if(!mayRemove(w,e,x,y,z))break;w.setBlockToAir(x,y,z);}e.cursor++;}
            d.markDirty();if(e.cursor>=e.limit){if(w.getBlock(e.x,e.y,e.z)==LaunchFacilityRegistry.facility){if(!mayRemove(w,e,e.x,e.y,e.z))continue;w.setBlockToAir(e.x,e.y,e.z);}ItemStack kit=new ItemStack(LaunchFacilityRegistry.facility);NBTTagCompound tag=new NBTTagCompound();tag.setTag("Controller",e.payload.copy());kit.setTagCompound(tag);w.spawnEntityInWorld(new EntityItem(w,e.x+.5,e.y+.5,e.z+.5,kit));it.remove();d.markDirty();}}
    }
    private static boolean mayRemove(World w,Entry e,int x,int y,int z){try{EntityPlayerMP p=net.minecraftforge.common.util.FakePlayerFactory.get((net.minecraft.world.WorldServer)w,new com.mojang.authlib.GameProfile(UUID.fromString(e.owner),"[LC39 recovery]"));p.setPosition(x+.5,y+.5,z+.5);return !net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(new net.minecraftforge.event.world.BlockEvent.BreakEvent(x,y,z,w,w.getBlock(x,y,z),w.getBlockMetadata(x,y,z),p));}catch(RuntimeException failure){return false;}}
    @Override public void readFromNBT(NBTTagCompound n){entries.clear();NBTTagList l=n.getTagList("Facilities",10);for(int i=0;i<Math.min(128,l.tagCount());i++){NBTTagCompound v=l.getCompoundTagAt(i);Entry e=new Entry();e.id=v.getString("Id");e.owner=v.getString("Owner");e.dim=v.getInteger("Dim");e.x=v.getInteger("X");e.y=v.getInteger("Y");e.z=v.getInteger("Z");e.facing=BlockSpaceMachine.front(v.getInteger("Facing"));e.cursor=Math.max(0,Math.min(LaunchFacilityPlan.CELLS.size(),v.getInteger("Cursor")));e.limit=Math.max(0,Math.min(LaunchFacilityPlan.CELLS.size(),v.getInteger("Limit")));e.cleanup=v.getBoolean("Cleanup");e.payload=v.getCompoundTag("Payload");if(!e.id.isEmpty()&&e.y>=2&&e.y+LaunchFacilityPlan.MAX_Y<=254)entries.put(e.id,e);}}
    @Override public void writeToNBT(NBTTagCompound n){NBTTagList l=new NBTTagList();for(Entry e:entries.values()){NBTTagCompound v=new NBTTagCompound();v.setString("Id",e.id);v.setString("Owner",e.owner);v.setInteger("Dim",e.dim);v.setInteger("X",e.x);v.setInteger("Y",e.y);v.setInteger("Z",e.z);v.setInteger("Facing",e.facing);v.setInteger("Cursor",e.cursor);v.setInteger("Limit",e.limit);v.setBoolean("Cleanup",e.cleanup);v.setTag("Payload",e.payload);l.appendTag(v);}n.setTag("Facilities",l);}
}
